  "settings.communityShareHint": "Atskilt fra «Mine lyttinger» og av som standard. Albumvurderingene dine (uten kommentar) og lyttingene kontoen din mottar ETTER at du slår det på, inngår i offentlige, anonyme totaler som vises på en albumside fra tre ulike personer. Ingen individuelle data vises noen gang. Hvis du slår det av, fjernes bidraget ditt med en gang.",
  "settings.communityMeasuresReceive": "Motta analyseresultater fra fellesskapet",
